import { MeshBasicNodeMaterial, MeshStandardNodeMaterial, PlaneGeometry } from 'three/webgpu';
import { uv, vec3, mix, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, Vector3 } = ctx.THREE;
  const group = new Group();

  // Create local cleanup stack
  const timelines = [];
  const texturesToDispose = [];

  // 1. STAGE BACKDROP (Engineered gradient surface & frame)
  // Dimensions to satisfy the [-3.5, 3.5] x [-3, 2.5] frame
  const backdropGeo = new PlaneGeometry(7.2, 5.8);

  // Custom TSL Material for the engineered dark gradient background
  const backdropMat = new MeshBasicNodeMaterial();
  const cInk = color('#16161d');
  const cSurface = color('#0b0b10');
  backdropMat.colorNode = mix(cSurface, cInk, uv().y);

  const backdropMesh = new Mesh(backdropGeo, backdropMat);
  backdropMesh.position.set(0, 0, -1.5);
  group.add(backdropMesh);

  // Decorative Accent Pins / Framing Lines (Atelier Aesthetic)
  const frameGeo = new PlaneGeometry(4.0, 2.5);
  const frameMat = new MeshBasicNodeMaterial({
    color: '#ff2a38', // Signal Red Accent
    wireframe: true,
    transparent: true,
    opacity: 0.15
  });
  const frameMesh = new Mesh(frameGeo, frameMat);
  frameMesh.position.set(0, 0, -1.0);
  group.add(frameMesh);

  // 2. HERO SHOWPIECE SPRITE
  // Atlas region: 0, 0, 512, 320 -> Aspect Ratio: 1.6
  const spriteWidth = 4.2;
  const spriteHeight = 4.2 / 1.6;
  const spriteGeo = new PlaneGeometry(spriteWidth, spriteHeight);

  const spriteMat = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0.0, // Fade In via GSAP
    depthWrite: false
  });

  const spriteMesh = new Mesh(spriteGeo, spriteMat);
  spriteMesh.position.set(0, 0, 0.1);
  group.add(spriteMesh);

  // Contact Shadow Plane below the floating showpiece
  const shadowGeo = new PlaneGeometry(spriteWidth, 0.4);
  const shadowMat = new MeshBasicNodeMaterial({
    color: '#000000',
    transparent: true,
    opacity: 0.0,
    depthWrite: false
  });
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.position.set(0, -spriteHeight / 2 - 0.2, -0.2);
  shadowMesh.rotation.x = -Math.PI / 2.5;
  group.add(shadowMesh);

  // Load Image Asset via context
  const imageUrl = config.imageUrl || '/prism-mock/home/nodes/floating-accent.png';
  ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
    spriteMat.map = texture;
    spriteMat.needsUpdate = true;
    texturesToDispose.push(texture);

    // Fade in and slight scale settle
    const entranceTl = gsap.timeline();
    entranceTl.to(spriteMat, {
      opacity: 1,
      duration: 1.2,
      ease: 'power3.out'
    }, 0);

    entranceTl.to(spriteMesh.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 1.5,
      ease: 'power4.out'
    }, 0);

    entranceTl.to(shadowMat, {
      opacity: 0.55,
      duration: 1.5,
      ease: 'power3.out'
    }, 0.2);

    timelines.push(entranceTl);
  }).catch((err) => {
    console.warn('Failed to load hero sprite texture:', err);
  });

  // Scale down initially for entrance feel
  spriteMesh.scale.set(0.92, 0.92, 0.92);

  // 3. IDLE MOTION (Subtle breathing/levitation)
  const idleTl = gsap.timeline({ repeat: -1, yoyo: true });
  idleTl.to(spriteMesh.position, {
    y: 0.08,
    duration: 3.5,
    ease: 'sine.inOut'
  });
  idleTl.to(shadowMesh.scale, {
    x: 0.95,
    duration: 3.5,
    ease: 'sine.inOut'
  }, 0);
  timelines.push(idleTl);

  // Apply visual primitives if mapped from cinematicPrimitives
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((primitive) => {
      if (ctx.primitives[primitive.name]) {
        const primResult = ctx.primitives[primitive.name](group, primitive.params);
        if (primResult && primResult.cleanup) {
          group.userData.primitiveCleanup = primResult.cleanup;
        }
      }
    });
  }

  // 4. CLEANUP METHOD
  group.userData.cleanup = function () {
    timelines.forEach((tl) => tl.kill());
    texturesToDispose.forEach((tex) => tex.dispose());

    // Dispose geometries & materials
    backdropGeo.dispose();
    backdropMat.dispose();
    frameGeo.dispose();
    frameMat.dispose();
    spriteGeo.dispose();
    spriteMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();

    if (group.userData.primitiveCleanup) {
      group.userData.primitiveCleanup();
    }
  };

  return group;
}
